import Model from 'flarum/common/Model';
export default class ExternalExtension extends Model {
  extensionId = (() => Model.attribute('extensionId'))();
  name = (() => Model.attribute('name'))();
  title = (() => Model.attribute('title'))();
  description = (() => Model.attribute('description'))();
  iconUrl = (() => Model.attribute('iconUrl'))();
  icon = (() => Model.attribute('icon'))();
  highestVersion = (() => Model.attribute('highestVersion'))();
  httpUri = (() => Model.attribute('httpUri'))();
  vendor = (() => Model.attribute('vendor'))();
  isLocale = (() => Model.attribute('isLocale'))();
  downloads = (() => Model.attribute('downloads'))();
  abandoned = (() => Model.attribute('abandoned'))();
  installed = false;
  toLocalExtension() {
    return {
      id: this.extensionId(),
      name: this.name(),
      version: this.highestVersion() ?? '?',
      description: this.description(),
      icon: this.icon() || {
        name: 'fas fa-box-open',
        backgroundColor: '#117187',
        color: '#fff'
      },
      links: {
        website: this.httpUri()
      },
      extra: {
        'flarum-extension': {
          title: this.title()
        }
      }
    };
  }
}
flarum.reg.add('flarum-extension-manager', 'admin/models/ExternalExtension', ExternalExtension);